"use client"

// From chatcn, chat, voice and agent UI for shadcn: https://chatcn.dev

import * as React from "react"
import { forwardRef, createElement, type SVGAttributes, type ForwardRefExoticComponent, type RefAttributes } from "react"
import { cn } from "@/lib/utils"
import { Collapsible } from "@base-ui/react/collapsible"

/** chatcn theme variables and utilities this file uses, light and dark. */
const CHATCN_CSS = ":root{--chatcn-accent:var(--chatcn-gray-1000);--chatcn-bg:oklch(1 0 0);--chatcn-ease-out:cubic-bezier(0.23, 1, 0.32, 1);--chatcn-ease-standard:ease;--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill-active:var(--chatcn-gray-300);--chatcn-fill-hover:var(--chatcn-gray-200);--chatcn-gray-1000:oklch(0.145 0 0);--chatcn-gray-200:oklch(0.950 0 0);--chatcn-gray-300:oklch(0.930 0 0);--chatcn-gray-700:oklch(0.700 0 0);--chatcn-gray-800:oklch(0.525 0 0);--chatcn-gray-900:oklch(0.440 0 0);--chatcn-radius-md:8px;--chatcn-radius-xs:4px}.dark{--chatcn-accent:var(--chatcn-gray-1000);--chatcn-bg:oklch(0.145 0 0);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill-active:var(--chatcn-gray-300);--chatcn-fill-hover:var(--chatcn-gray-200);--chatcn-gray-1000:oklch(0.970 0 0);--chatcn-gray-200:oklch(0.225 0 0);--chatcn-gray-300:oklch(0.255 0 0);--chatcn-gray-700:oklch(0.500 0 0);--chatcn-gray-800:oklch(0.620 0 0);--chatcn-gray-900:oklch(0.720 0 0)}.chatcn-focus{}.chatcn-focus:focus-visible{outline: 2px solid var(--chatcn-accent); outline-offset: 2px;}"
if (typeof document !== "undefined" && !document.getElementById("chatcn-sources")) {
  const style = document.createElement("style")
  style.id = "chatcn-sources"
  style.textContent = CHATCN_CSS
  document.head.appendChild(style)
}

/* -------------------------------------------------------------------------------------------------
 * Types and helpers
 * -----------------------------------------------------------------------------------------------*/

export interface Source {
  /** Stable id, for example the AI SDK `sourceId`. Defaults to the URL. */
  id?: string
  url: string
  title?: string
  snippet?: string
  /** Defaults to the URL host without `www.`. */
  domain?: string
  /** Optional favicon URL. Falls back to a monochrome letter tile when missing or broken. */
  favicon?: string
}

/** A web source cited by the response. */
type ChatcnSourceUrlPart = {
  type: "source-url"
  sourceId: string
  url: string
  title?: string
}

/** Maps `source-url` parts to `Source` objects, dropping duplicate URLs. */
export function sourcesFromParts(parts: { type: string }[]): Source[] {
  const seen = new Set<string>()
  const out: Source[] = []
  for (const part of parts) {
    if (part.type !== "source-url") continue
    const p = part as ChatcnSourceUrlPart
    if (seen.has(p.url)) continue
    seen.add(p.url)
    out.push({ id: p.sourceId, url: p.url, title: p.title })
  }
  return out
}

/* -------------------------------------------------------------------------------------------------
 * SourceTile
 * -----------------------------------------------------------------------------------------------*/

export interface SourceTileProps extends React.ComponentProps<"span"> {
  source: Pick<Source, "url" | "domain" | "favicon">
}

/** Host of a URL without `www.`, or the input when it is not a URL. */
export function getSourceDomain(url: string) {
  try {
    return new URL(url).hostname.replace(/^www\./, "")
  } catch {
    return url
  }
}

/**
 * A favicon slot. Without a favicon it shows the domain's first letter on a gray tile: no brand
 * colors, so a row of sources stays as calm as the text around it.
 */
export function SourceTile({ source, className, ...props }: SourceTileProps) {
  const [broken, setBroken] = React.useState(false)
  const domain = source.domain ?? getSourceDomain(source.url)
  const letter =
    domain
      .replace(/^[^a-z0-9]+/i, "")
      .charAt(0)
      .toUpperCase() || "?"
  return (
    <span
      data-slot="source-tile"
      aria-hidden="true"
      className={cn(
        "bg-(color:--chatcn-fill-active) text-(color:--chatcn-fg-muted) rounded-(--chatcn-radius-xs) relative grid size-[1.125rem] shrink-0 place-items-center overflow-hidden",
        "text-[0.75rem]/[1rem] leading-none font-medium select-none",
        className,
      )}
      {...props}
    >
      {source.favicon && !broken ? (
        <img
          src={source.favicon}
          alt=""
          width={18}
          height={18}
          loading="lazy"
          onError={() => setBroken(true)}
          className="size-full object-cover"
        />
      ) : (
        letter
      )}
    </span>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Sources
 * -----------------------------------------------------------------------------------------------*/

export interface SourcesProps extends Omit<React.ComponentProps<"div">, "children"> {
  sources: Source[]
  /** Trigger label. Defaults to "12 sources". */
  label?: React.ReactNode
  /** How many tiles to stack in the trigger. Defaults to 4. */
  maxTiles?: number
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

const iconNode: IconNode = [
  ["path", {"d":"m6 9.25 4.23 4.23a2.5 2.5 0 0 0 3.54 0L18 9.25"}],
]

const ChevronDownIcon: Icon = /* @__PURE__ */ createIcon("chevron-down", iconNode)

function SourceRow({ source, index }: { source: Source; index: number }) {
  const domain = source.domain ?? getSourceDomain(source.url)
  return (
    <li id={source.id ? `source-${source.id}` : undefined} className="min-w-0">
      <a
        href={source.url}
        target="_blank"
        rel="noreferrer"
        className={cn(
          "chatcn-focus rounded-(--chatcn-radius-md) group/source grid grid-cols-[1.25rem_1fr] gap-x-2 px-1.5 py-2",
          "hover:bg-(color:--chatcn-fill-hover) ease-(--chatcn-ease-standard) transition-colors duration-150",
        )}
      >
        <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) pt-px text-end font-medium tabular-nums">
          {index}
        </span>
        <span className="flex min-w-0 flex-col gap-0.5">
          <span className="flex min-w-0 items-center gap-2">
            <SourceTile source={source} className="size-4" />
            <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) truncate">{domain}</span>
          </span>
          <span className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) truncate font-medium">
            {source.title ?? domain}
          </span>
          {source.snippet ? (
            <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) line-clamp-2 text-pretty">
              {source.snippet}
            </span>
          ) : null}
        </span>
      </a>
    </li>
  )
}

/**
 * The sources behind an answer. Collapsed: a stack of letter tiles and "12 sources". Expanded: a
 * numbered list whose numbers match the inline citations.
 */
export function Sources({
  sources,
  label,
  maxTiles = 4,
  open,
  defaultOpen = false,
  onOpenChange,
  className,
  ...props
}: SourcesProps) {
  if (sources.length === 0) return null
  const count = sources.length
  const stack = sources.slice(0, maxTiles)

  return (
    <Collapsible.Root
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
      render={<div />}
      data-slot="sources"
      className={cn("group/sources text-[0.875rem]/[1.25rem] tracking-[-0.003em] min-w-0", className)}
      {...props}
    >
      <Collapsible.Trigger
        className={cn(
          "chatcn-focus rounded-(--chatcn-radius-md) inline-flex h-8 items-center gap-2 ps-1.5 pe-2 select-none",
          "text-(color:--chatcn-fg-muted) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg) ease-(--chatcn-ease-standard) transition-colors duration-150",
          "data-[panel-open]:text-(color:--chatcn-fg) pointer-coarse:h-11",
        )}
      >
        <span className="flex items-center">
          {stack.map((source, i) => (
            <SourceTile
              key={source.id ?? source.url}
              source={source}
              // Overlap by 4 px; the ring cuts each tile out of the one beneath it.
              className={cn("ring-(color:--chatcn-bg) size-5 ring-2", i > 0 && "-ms-1")}
            />
          ))}
        </span>
        <span className="text-[0.8125rem]/[1.25rem] font-medium tabular-nums">
          {label ?? `${count} ${count === 1 ? "source" : "sources"}`}
        </span>
        <ChevronDownIcon
          aria-hidden="true"
          className={cn(
            "text-(color:--chatcn-fg-subtle) ease-(--chatcn-ease-out) size-3.5 shrink-0 transition-[rotate] duration-200",
            "group-data-[open]/sources:rotate-180 motion-reduce:transition-none",
          )}
        />
      </Collapsible.Trigger>
      <Collapsible.Panel
        className={cn(
          "h-(--collapsible-panel-height) overflow-hidden",
          "ease-(--chatcn-ease-out) transition-[height,opacity] duration-200 motion-reduce:transition-none",
          "data-[ending-style]:h-0 data-[ending-style]:opacity-0 data-[ending-style]:duration-150",
          "data-[starting-style]:h-0 data-[starting-style]:opacity-0",
        )}
      >
        <ol data-slot="sources-list" className="flex flex-col pt-1">
          {sources.map((source, i) => (
            <SourceRow key={source.id ?? source.url} source={source} index={i + 1} />
          ))}
        </ol>
      </Collapsible.Panel>
    </Collapsible.Root>
  )
}

export default Sources

